entries[31354] = { ["name"] = "Rezept: Fläschchen der Titanen", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Alchemie\n(300)\nBenötigt Die Sha'tar\n- Ehrfürchtig\nBenutzen: Lehrt Euch die Herstellung eines Fläschchens der Titanen.\nVerkaufspreis:\nFläschchen der Titanen\nBenötigt Stufe 50\nBenutzen: Erhöht die maximale Gesundheit des Spielers 1 Stunde lang um 400 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Gromsblut (7), Steinschuppenöl (3), Schwarzer Lotus , Kristallphiole" }
entries[31355] = { ["name"] = "Rezept: Fläschchen der obersten Macht", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Alchemie\n(300)\nBenötigt Hüter der Zeit\n- Ehrfürchtig\nBenutzen: Lehrt Euch die Herstellung eines Fläschchens der obersten Macht.\nVerkaufspreis:\nFläschchen der obersten Macht\nBenötigt Stufe 50\nBenutzen: Erhöht die Zaubermacht 1 Stunde lang um 70 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Traumblatt (7), Bergsilbersalbei (3), Schwarzer Lotus , Kristallphiole" }
entries[31356] = { ["name"] = "Rezept: Fläschchen der destillierten Weisheit", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Alchemie\n(300)\nBenötigt Expedition des Cenarius\n- Ehrfürchtig\nBenutzen: Lehrt Euch die Herstellung eines Fläschchens der destillierten Weisheit.\nVerkaufspreis:\nFläschchen der destillierten Weisheit\nBenötigt Stufe 50\nBenutzen: Erhöht die Intelligenz 1 Stunde lang um 65 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Traumblatt (7), Eiskappe (3), Schwarzer Lotus , Kristallphiole" }
